// Package tasks is the catalog of agent-run tasks: what the agent is asked to build (TASK.md + RULES.md), the
// shared mock data it gets, and the automatic checks that score the run.
//
// The catalog is embedded. ARENA_TASKS_HIDDEN_DIR/<slug>/checks.json (generated by gen_data.py --hidden, kept out of
// git) adds hidden checks on other records of the same data: they count in the score, but their names, requests and
// failures are not shown anywhere, so an agent can't fit its answers to TASK.md's examples. task.json and data/ are
// generated by gen_data.py.
package tasks

import (
	"archive/zip"
	"bytes"
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

//go:embed catalog
var catalog embed.FS

// Text is a string shown on the site in both of its languages.
type Text struct {
	En string `json:"en"`
	Ru string `json:"ru"`
}

// Check is one automatic check against the running app, run by verify.py in order. An HTTP check calls Method Path
// ({var} in paths and expect paths = a value saved by an earlier check) and compares the status and the JSON. A page
// check (Page set) opens the path in a browser and wants every Text on the rendered page (at least Min of them when
// Min is set). A browser check (Browser set, named "browser: …") clicks through a flow; verify.py reads its steps.
type Check struct {
	Name     string            `json:"name"`
	Method   string            `json:"method,omitempty"`
	Path     string            `json:"path,omitempty"`
	Body     any               `json:"body,omitempty"`
	Auth     string            `json:"auth,omitempty"` // saved value sent as the Bearer token
	Status   int               `json:"status,omitempty"`
	StatusIn []int             `json:"status_in,omitempty"`
	Expect   []map[string]any  `json:"expect,omitempty"`
	Save     map[string]string `json:"save,omitempty"` // name → JSON path in the response
	Page     string            `json:"page,omitempty"`
	Text     []string          `json:"text,omitempty"`
	Min      int               `json:"min,omitempty"`
	Browser  json.RawMessage   `json:"browser,omitempty"`
	Hidden   bool              `json:"hidden,omitempty"` // from the hidden set: verify.py reports no details
}

// Kinds of task. A build task is a product to a spec, ranked by the share of checks passed. The others have only a
// brief and are ranked by people's blind votes, trying the task's Scenarios in both apps; their checks just gate the
// run (it starts, it shows the data). Invent: rethink a product everyone knows. Startup: an MVP that solves one real
// person's problem, as close to a product people would pay for as the agent can get.
const (
	KindBuild   = "build"
	KindInvent  = "invent"
	KindStartup = "startup"
)

type Task struct {
	Slug        string `json:"slug"`
	Order       int    `json:"order"`
	Kind        string `json:"kind"`
	Scenarios   []Text `json:"scenarios,omitempty"` // what a voter tries in both apps
	Title       Text   `json:"title"`
	Tagline     Text   `json:"tagline"`
	TimeLimitS  int    `json:"time_limit_s"`
	TokenBudget int64  `json:"token_budget"`
	UI          bool   `json:"ui"` // the app has a web UI: the HTML check, screenshots and the live preview apply
	// UIText: strings the home page must show (as HTML or SVG text) right after start, i.e. the seed data.
	UIText []string `json:"ui_text,omitempty"`
	Checks []Check  `json:"checks"` // the public checks, listed on the task page
	Hidden []Check  `json:"-"`      // the hidden ones, run after them (see the package doc)

	TaskMD    string            `json:"-"` // TASK.md with RULES.md appended: exactly what the agent reads
	Brief     string            `json:"-"` // what the site shows: the product part of TASK.md (see siteBrief)
	DataFiles map[string][]byte `json:"-"` // name → content, from data/

	// Hashes of what a run gets, set by Load (a run's manifest keeps them): TASK.md as the agent reads it, the data
	// files, and the check spec (Checks, UI, UIText) verify.py runs.
	TaskMDHash, DataHash, ChecksHash string `json:"-"`
}

func sum(b []byte) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:])
}

// hash fills the task's hashes.
func (t *Task) hash() error {
	t.TaskMDHash = sum([]byte(t.TaskMD))
	var data bytes.Buffer
	for _, n := range t.DataNames() {
		fmt.Fprintf(&data, "%s\x00%d\x00", n, len(t.DataFiles[n]))
		data.Write(t.DataFiles[n])
	}
	t.DataHash = sum(data.Bytes())
	// The hidden checks count in the score, so a new hidden set is a new checks version (the hash reveals nothing).
	spec, err := json.Marshal(map[string]any{"checks": t.AllChecks(), "ui": t.UI, "ui_text": t.UIText})
	t.ChecksHash = sum(spec)
	return err
}

var all []*Task

// siteBrief is the part of TASK.md people read on the site: the product, without the "# Title" (the page has it)
// and without the sections from "## Data" on, which are for the agent.
func siteBrief(md string) string {
	md = strings.TrimSpace(md)
	if strings.HasPrefix(md, "# ") {
		if i := strings.IndexByte(md, '\n'); i >= 0 {
			md = md[i+1:]
		} else {
			md = ""
		}
	}
	if i := strings.Index(md, "\n## Data"); i >= 0 {
		md = md[:i]
	}
	return strings.TrimSpace(md) + "\n"
}

// Load reads the embedded catalog; hiddenDir ("" = none) adds the hidden checks per task.
func Load(hiddenDir string) error {
	rules, err := catalog.ReadFile("catalog/RULES.md")
	if err != nil {
		return err
	}
	entries, err := catalog.ReadDir("catalog")
	if err != nil {
		return err
	}
	var out []*Task
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		slug := e.Name()
		dir := "catalog/" + slug
		raw, err := catalog.ReadFile(dir + "/task.json")
		if err != nil {
			return fmt.Errorf("tasks: %s: %w", slug, err)
		}
		t := &Task{Slug: slug, DataFiles: map[string][]byte{}}
		if err := json.Unmarshal(raw, t); err != nil {
			return fmt.Errorf("tasks: %s/task.json: %w", slug, err)
		}
		md, err := catalog.ReadFile(dir + "/TASK.md")
		if err != nil {
			return fmt.Errorf("tasks: %s: %w", slug, err)
		}
		t.Brief = siteBrief(string(md))
		t.TaskMD = strings.TrimSpace(string(md)) + "\n\n" + strings.TrimSpace(string(rules)) + "\n"
		if hiddenDir != "" {
			if b, err := os.ReadFile(filepath.Join(hiddenDir, slug, "checks.json")); err == nil {
				if err := json.Unmarshal(b, &t.Hidden); err != nil {
					return fmt.Errorf("tasks: hidden %s/checks.json: %w", slug, err)
				}
				for i := range t.Hidden {
					t.Hidden[i].Name = fmt.Sprintf("hidden check %d", i+1)
					t.Hidden[i].Hidden = true
				}
			} else if !os.IsNotExist(err) {
				return fmt.Errorf("tasks: hidden %s/checks.json: %w", slug, err)
			}
		}
		err = fs.WalkDir(catalog, dir+"/data", func(p string, d fs.DirEntry, err error) error {
			if err != nil || d.IsDir() {
				return err
			}
			b, err := catalog.ReadFile(p)
			t.DataFiles[path.Base(p)] = b
			return err
		})
		if err != nil {
			return fmt.Errorf("tasks: %s data: %w", slug, err)
		}
		if t.Kind == "" {
			t.Kind = KindBuild
		}
		if t.Kind != KindBuild && t.Kind != KindInvent && t.Kind != KindStartup {
			return fmt.Errorf("tasks: %s: unknown kind %q", slug, t.Kind)
		}
		if t.TimeLimitS <= 0 || t.TokenBudget <= 0 {
			return fmt.Errorf("tasks: %s: time_limit_s and token_budget are required", slug)
		}
		if err := t.hash(); err != nil {
			return fmt.Errorf("tasks: %s: %w", slug, err)
		}
		out = append(out, t)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Order < out[j].Order })
	all = out
	return nil
}

func All() []*Task { return all }

func BySlug(slug string) *Task {
	for _, t := range all {
		if t.Slug == slug {
			return t
		}
	}
	return nil
}

// DataNames lists the data files, sorted.
func (t *Task) DataNames() []string {
	names := make([]string, 0, len(t.DataFiles))
	for n := range t.DataFiles {
		names = append(names, n)
	}
	sort.Strings(names)
	return names
}

// Workspace is what the agent finds in /work when it starts: TASK.md and data/.
func (t *Task) Workspace() map[string][]byte {
	files := map[string][]byte{"TASK.md": []byte(t.TaskMD)}
	for n, b := range t.DataFiles {
		files["data/"+n] = b
	}
	return files
}

// BundleZip is the workspace as a zip (public: anyone can see exactly what the agents get).
func (t *Task) BundleZip() ([]byte, error) {
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	files := t.Workspace()
	names := make([]string, 0, len(files))
	for n := range files {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		w, err := zw.Create(t.Slug + "/" + n)
		if err != nil {
			return nil, err
		}
		if _, err := w.Write(files[n]); err != nil {
			return nil, err
		}
	}
	if err := zw.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// Names of the checks a run records, in the order verify.py runs them (keep in sync with verify.py and the
// worker, which adds the start check).
const (
	CheckStart    = "app starts with start.sh"
	CheckHTML     = "home page serves HTML"
	CheckSeedPage = "page shows the seed data"
)

// AllChecks is what verify.py runs after the UI checks: the public checks, then the hidden ones on the state the
// public ones left (gen_data.py replays it).
func (t *Task) AllChecks() []Check {
	return append(append([]Check{}, t.Checks...), t.Hidden...)
}

// CheckNames lists the public checks of a run of this task, in order (the hidden ones follow them).
func (t *Task) CheckNames() []string {
	names := []string{CheckStart}
	if t.UI {
		names = append(names, CheckHTML)
		if len(t.UIText) > 0 {
			names = append(names, CheckSeedPage)
		}
	}
	for _, c := range t.Checks {
		names = append(names, c.Name)
	}
	return names
}
